export const DEFAULT_CATEGORY_TRANSLATIONS: Record<string, Record<string, string>> = {
  Food: { bn: 'খাবার', hi: 'भोजन', es: 'Comida', ar: 'طعام', fr: 'Alimentation', de: 'Essen', zh: '餐饮', ja: '食費' },
  Transport: { bn: 'যাতায়াত', hi: 'परिवहन', es: 'Transporte', ar: 'مواصلات', fr: 'Transport', de: 'Transport', zh: '交通', ja: '交通費' },
  Bills: { bn: 'বিল', hi: 'बिल', es: 'Facturas', ar: 'فواتير', fr: 'Factures', de: 'Rechnungen', zh: '账单', ja: '光熱費' },
  Shopping: { bn: 'কেনাকাটা', hi: 'खरीदारी', es: 'Compras', ar: 'تسوق', fr: 'Achats', de: 'Einkaufen', zh: '购物', ja: '買い物' },
  Health: { bn: 'স্বাস্থ্য', hi: 'स्वास्थ्य', es: 'Salud', ar: 'صحة', fr: 'Santé', de: 'Gesundheit', zh: '医疗', ja: '医療' },
  Education: { bn: 'শিক্ষা', hi: 'शिक्षा', es: 'Educación', ar: 'تعليم', fr: 'Éducation', de: 'Bildung', zh: '教育', ja: '教育' },
  Salary: { bn: 'বেতন', hi: 'वेतन', es: 'Salario', ar: 'راتب', fr: 'Salaire', de: 'Gehalt', zh: '薪水', ja: '給与' },
  Business: { bn: 'ব্যবসা', hi: 'व्यापार', es: 'Negocios', ar: 'أعمال', fr: 'Affaires', de: 'Geschäft', zh: '商务', ja: 'ビジネス' },
  Investment: { bn: 'বিনিয়োগ', hi: 'निवेश', es: 'Inversión', ar: 'استثمار', fr: 'Investissement', de: 'Investition', zh: '投资', ja: '投資' },
  Freelance: { bn: 'ফ্রিল্যান্সিং', hi: 'फ्रीलांस', es: 'Freelance', ar: 'عمل حر', fr: 'Freelance', de: 'Freiberuflich', zh: '自由职业', ja: '副業' },
  Others: { bn: 'অন্যান্য', hi: 'अन्य', es: 'Otros', ar: 'أخرى', fr: 'Autres', de: 'Sonstiges', zh: '其他', ja: 'その他' },
};

export function translateCategory(name: string, lang?: AppLanguage): string {
  if (!name) return name;
  const currentLang = lang || getAppLanguage();
  if (currentLang === 'en') return name;
  const mapped = DEFAULT_CATEGORY_TRANSLATIONS[name];
  if (mapped && mapped[currentLang]) {
    return mapped[currentLang];
  }
  return name;
}

export function useTranslateCategory(): (name: string) => string {
  const { lang } = useTranslation();
  return (name: string) => translateCategory(name, lang);
}

export function getAppLanguage(): AppLanguage {
  if (typeof window === 'undefined') return 'en';
  const saved = localStorage.getItem('app_language') as AppLanguage | null;
  if (saved && saved in TRANSLATIONS) return saved;
  return 'en';
}

export function setAppLanguage(lang: AppLanguage): void {
  if (typeof window === 'undefined') return;
  localStorage.setItem('app_language', lang);
  document.documentElement.setAttribute('lang', lang);
  const rtlLanguages = ['ar', 'ur', 'fa'];
  document.documentElement.setAttribute('dir', rtlLanguages.includes(lang) ? 'rtl' : 'ltr');
  window.dispatchEvent(new CustomEvent('applanguagechange', { detail: lang }));
}

export function translate(key: string, lang?: AppLanguage): string {
  const activeLang = lang || getAppLanguage();
  return TRANSLATIONS[activeLang]?.[key] || TRANSLATIONS.en[key] || key;
}

export function useTranslation() {
  const [lang, setLangState] = useState<AppLanguage>(() => getAppLanguage());

  useEffect(() => {
    const current = getAppLanguage();
    setLangState(current);
    document.documentElement.setAttribute('lang', current);
    const rtlLanguages = ['ar', 'ur', 'fa'];
    document.documentElement.setAttribute('dir', rtlLanguages.includes(current) ? 'rtl' : 'ltr');

    const handleLangChange = (e: Event) => {
      const detail = (e as CustomEvent).detail as AppLanguage | undefined;
      const next = detail || getAppLanguage();
      setLangState(next);
      document.documentElement.setAttribute('lang', next);
      document.documentElement.setAttribute('dir', rtlLanguages.includes(next) ? 'rtl' : 'ltr');
    };
    window.addEventListener('applanguagechange', handleLangChange);
    window.addEventListener('storage', handleLangChange);
    return () => {
      window.removeEventListener('applanguagechange', handleLangChange);
      window.removeEventListener('storage', handleLangChange);
    };
  }, []);

  const t = (key: string): string => {
    return TRANSLATIONS[lang]?.[key] || TRANSLATIONS.en[key] || key;
  };

  return { lang, language: lang, setLang: setAppLanguage, setLanguage: setAppLanguage, t };
}

export function formatMonthYear(year: number, monthIndex: number, lang?: AppLanguage): string {
  const activeLang = lang || getAppLanguage();
  const localeMap: Record<string, string> = {
    en: 'en-US', bn: 'bn-BD', hi: 'hi-IN', es: 'es-ES', ar: 'ar-EG',
    fr: 'fr-FR', de: 'de-DE', zh: 'zh-CN', ja: 'ja-JP', pt: 'pt-BR',
    ru: 'ru-RU', ur: 'ur-PK', id: 'id-ID', tr: 'tr-TR', it: 'it-IT',
    ko: 'ko-KR', vi: 'vi-VN', th: 'th-TH', ms: 'ms-MY', fa: 'fa-IR',
    nl: 'nl-NL', pl: 'pl-PL', sv: 'sv-SE', ta: 'ta-IN',
  };
  const date = new Date(year, monthIndex, 1);
  return date.toLocaleDateString(localeMap[activeLang] || 'en-US', {
    month: 'long',
    year: 'numeric',
  });
}

export function formatLocalizedNumber(num: number | string, lang?: AppLanguage): string {
  const activeLang = lang || getAppLanguage();
  const n = typeof num === 'string' ? parseFloat(num) : num;
  if (isNaN(n)) return String(num);
  const localeMap: Record<string, string> = {
    en: 'en-US',
    bn: 'bn-BD-u-nu-beng',
    hi: 'hi-IN-u-nu-deva',
    ar: 'ar-EG-u-nu-arab',
    ur: 'ur-PK-u-nu-arabext',
    fa: 'fa-IR-u-nu-arabext',
    es: 'es-ES',
    fr: 'fr-FR',
    de: 'de-DE',
    zh: 'zh-CN-u-nu-hanidec',
    ja: 'ja-JP-u-nu-hanidec',
    pt: 'pt-BR',
    ru: 'ru-RU',
    id: 'id-ID',
    tr: 'tr-TR',
    it: 'it-IT',
    ko: 'ko-KR',
    vi: 'vi-VN',
    th: 'th-TH-u-nu-thai',
    ms: 'ms-MY',
    nl: 'nl-NL',
    pl: 'pl-PL',
    sv: 'sv-SE',
    ta: 'ta-IN-u-nu-tamldec',
  };
  let formatted = '';
  try {
    formatted = new Intl.NumberFormat(localeMap[activeLang] || 'en-US').format(n);
  } catch {
    formatted = new Intl.NumberFormat('en-US').format(n);
  }
  const nativeDigits: Record<string, string[]> = {
    bn: ['০', '১', '২', '৩', '৪', '৫', '৬', '৭', '৮', '৯'],
    hi: ['०', '१', '२', '३', '४', '५', '६', '७', '८', '९'],
    ar: ['٠', '١', '٢', '٣', '٤', '٥', '٦', '٧', '٨', '٩'],
    ur: ['۰', '۱', '۲', '۳', '۴', '۵', '۶', '۷', '۸', '۹'],
    fa: ['۰', '۱', '۲', '۳', '۴', '۵', '۶', '۷', '۸', '۹'],
    zh: ['〇', '一', '二', '三', '四', '五', '六', '七', '八', '九'],
    ja: ['〇', '一', '二', '三', '四', '五', '六', '七', '八', '九'],
    th: ['๐', '๑', '๒', '๓', '๔', '๕', '๖', '๗', '๘', '๙'],
    ta: ['௦', '௧', '௨', '௩', '௪', '௫', '௬', '௭', '௮', '௯'],
  };
  const digits = nativeDigits[activeLang];
  return digits ? formatted.replace(/[0-9]/g, (d) => digits[parseInt(d, 10)]) : formatted;
}
